<?php
use Illuminate\Support\Facades\Route;
use App\Http\Controllers\DashboardController;
use App\Http\Controllers\RoutineController;
use App\Http\Controllers\OnboardingController;
use App\Http\Controllers\TaskController;
use App\Http\Controllers\PrayerController;
use App\Http\Controllers\PrayerSettingController;
use App\Http\Controllers\WaterController;
use App\Http\Controllers\WeightController;
use App\Http\Controllers\WalkingController;
use App\Http\Controllers\ExerciseController;
use App\Http\Controllers\MealController;
use App\Http\Controllers\SleepController;
use App\Http\Controllers\OfficeController;
use App\Http\Controllers\ProjectController;
use App\Http\Controllers\FreelanceIncomeController;
use App\Http\Controllers\LearningController;
use App\Http\Controllers\HabitController;
use App\Http\Controllers\FinanceController;
use App\Http\Controllers\CalendarController;
use App\Http\Controllers\ReportController;
use App\Http\Controllers\SettingsController;
use App\Http\Controllers\ProfileController;
use App\Http\Controllers\NotificationController;
use App\Http\Controllers\ExportController;
Route::get('/',fn()=>auth()->check()?redirect()->route('dashboard'):redirect()->route('login'));
Route::middleware(['auth'])->group(function(){
 Route::get('/dashboard',DashboardController::class)->name('dashboard');
 Route::get('/my-day',[TaskController::class,'index'])->name('my-day');
 Route::resource('tasks',TaskController::class)->except(['show']);
 Route::post('tasks/{task}/complete',[TaskController::class,'complete'])->name('tasks.complete');
 Route::post('tasks/{task}/reopen',[TaskController::class,'reopen'])->name('tasks.reopen');
 Route::post('tasks/{task}/postpone',[TaskController::class,'postpone'])->name('tasks.postpone');
 Route::post('tasks/{task}/duplicate',[TaskController::class,'duplicate'])->name('tasks.duplicate');
 // Salah
 Route::get('salah',[PrayerController::class,'index'])->name('salah.index');
 Route::post('salah/status',[PrayerController::class,'updateStatus'])->name('salah.status');
 Route::get('salah/history',[PrayerController::class,'history'])->name('salah.history');
 Route::get('salah/settings',[PrayerSettingController::class,'edit'])->name('salah.settings');
 Route::put('salah/settings',[PrayerSettingController::class,'update'])->name('salah.settings.update');
 // Health
 Route::resource('health/water',WaterController::class)->except(['show'])->names('health.water')->parameters(['water'=>'water']);
 Route::resource('health/weight',WeightController::class)->except(['show'])->names('health.weight')->parameters(['weight'=>'weight']);
 Route::resource('health/walking',WalkingController::class)->except(['show'])->names('health.walking')->parameters(['walking'=>'walking']);
 Route::resource('health/exercise',ExerciseController::class)->except(['show'])->names('health.exercise')->parameters(['exercise'=>'exercise']);
 Route::get('health',fn()=>redirect()->route('health.water.index'))->name('health.index');
 Route::resource('meals',MealController::class)->except(['show']);
 Route::resource('sleep',SleepController::class)->except(['show']);
 Route::post('sleep/start',[SleepController::class,'start'])->name('sleep.start');
 Route::post('sleep/{sleep}/end',[SleepController::class,'end'])->name('sleep.end');
 Route::resource('office',OfficeController::class)->except(['show'])->parameters(['office'=>'office']);
 Route::post('office/salary',[OfficeController::class,'storeSalary'])->name('office.salary');
 Route::resource('freelancing/projects',ProjectController::class)->except(['show'])->names('freelancing.projects')->parameters(['projects'=>'project']);
 Route::resource('freelancing/income',FreelanceIncomeController::class)->except(['show'])->names('freelancing.income')->parameters(['income'=>'income']);
 Route::get('freelancing',fn()=>redirect()->route('freelancing.projects.index'))->name('freelancing.index');
 Route::get('learning',[LearningController::class,'index'])->name('learning.index');
 Route::get('learning/goal/create',[LearningController::class,'createGoal'])->name('learning.goal.create'); Route::post('learning/goal',[LearningController::class,'storeGoal'])->name('learning.goal.store');
 Route::get('learning/session/create',[LearningController::class,'createSession'])->name('learning.session.create'); Route::post('learning/session',[LearningController::class,'storeSession'])->name('learning.session.store');
 Route::get('learning/goal/{goal}/edit',[LearningController::class,'editGoal'])->name('learning.goal.edit'); Route::put('learning/goal/{goal}',[LearningController::class,'updateGoal'])->name('learning.goal.update'); Route::delete('learning/goal/{goal}',[LearningController::class,'destroyGoal'])->name('learning.goal.destroy'); Route::delete('learning/session/{session}',[LearningController::class,'destroySession'])->name('learning.session.destroy');
 Route::resource('habits',HabitController::class)->except(['show']); Route::post('habits/{habit}/toggle',[HabitController::class,'toggle'])->name('habits.toggle');
 Route::resource('finance',FinanceController::class)->except(['show'])->parameters(['finance'=>'financial']);
 Route::get('calendar',[CalendarController::class,'index'])->name('calendar.index');
 Route::get('reports/daily',[ReportController::class,'daily'])->name('reports.daily'); Route::get('reports/weekly',[ReportController::class,'weekly'])->name('reports.weekly'); Route::get('reports/monthly',[ReportController::class,'monthly'])->name('reports.monthly'); Route::get('reports/yearly',[ReportController::class,'yearly'])->name('reports.yearly'); Route::get('reports/custom',[ReportController::class,'custom'])->name('reports.custom'); Route::get('reports/chart-data',[ReportController::class,'chartData'])->name('reports.chart');
 Route::get('settings',[SettingsController::class,'index'])->name('settings.index'); Route::put('settings',[SettingsController::class,'update'])->name('settings.update');
 Route::get('profile',[ProfileController::class,'edit'])->name('profile.edit'); Route::patch('profile',[ProfileController::class,'update'])->name('profile.update'); Route::delete('profile',[ProfileController::class,'destroy'])->name('profile.destroy');
 Route::get('settings/notifications',[NotificationController::class,'index'])->name('notifications.index'); Route::post('settings/notifications/subscription',[NotificationController::class,'storeSubscription'])->name('notifications.subscription'); Route::post('settings/notifications/reminder',[NotificationController::class,'storeReminder'])->name('notifications.reminder'); Route::delete('settings/notifications/reminder/{reminder}',[NotificationController::class,'destroyReminder'])->name('notifications.reminder.destroy');
 Route::post('settings/notifications/test',[NotificationController::class,'sendTest'])->name('notifications.test');
 Route::get('notifications',[NotificationController::class,'inbox'])->name('notifications.inbox'); Route::post('notifications/{log}/read',[NotificationController::class,'markRead'])->name('notifications.read'); Route::post('notifications/read-all',[NotificationController::class,'markAllRead'])->name('notifications.readAll');
 Route::get('routine',[RoutineController::class,'index'])->name('routine.index'); Route::post('routine',[RoutineController::class,'store'])->name('routine.store'); Route::get('routine/{template}/edit',[RoutineController::class,'edit'])->name('routine.edit'); Route::put('routine/{template}',[RoutineController::class,'update'])->name('routine.update'); Route::delete('routine/{template}',[RoutineController::class,'destroy'])->name('routine.destroy');
 Route::get('welcome',[OnboardingController::class,'index'])->name('onboarding.index'); Route::post('welcome/dismiss',[OnboardingController::class,'dismiss'])->name('onboarding.dismiss');
 Route::get('help',fn()=>view('help.index'))->name('help');
 Route::get('export',[ExportController::class,'index'])->name('export.index'); Route::get('export/full',[ExportController::class,'full'])->name('export.full'); Route::get('export/{table}.csv',[ExportController::class,'csv'])->name('export.csv');
});
require __DIR__.'/auth.php';
